-- One Sky: a light can sit at a real city, not only at the centre of a time zone.
--
--  1. places.tz is now a generic PLACE KEY. The 418 zone rows keep their IANA zone name as key;
--     each city of 50k+ people (src/lib/cities.ts, GeoNames) gets the key 'g' || geonameid.
--  2. places.zone_tz is the real IANA zone of the place (= tz for the zone rows). Everything that
--     computes a zone, and everything stored or returned to clients as a time zone (lanterns.tz,
--     echo_waves.from_tz), uses zone_tz. echoes.tz keeps the place KEY: send_wave falls back to it
--     to look the caller's place up when an old client sends no p_tz.
--  3. places.jitter is how far (degrees, per axis) a position may sit from the place centre:
--     0.61 for zone rows (the client jitters by up to 0.6), 0.21 for cities (up to 0.2).
--
-- Every signature and return shape is unchanged; a client that sends an IANA zone name in p_tz
-- behaves exactly as before.

-- ───────────────────────────── places ─────────────────────────────

alter table public.places add column zone_tz text;
alter table public.places add column jitter real not null default 0.61;
update public.places set zone_tz = tz;
alter table public.places alter column jitter drop default;

